 foreach(['a','b']as $key){$account=$prefix.$key;$mid=Directory::saveMerchant(1,['name'=>$account,'account'=>$account,'password'=>'GeoLocal2026!']);$u=(int)Db::name('oem_merchant')->where('id',$mid)->value('user_id');$c=curl_init('http://localhost:8090/api/merchant/login');curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode(['account'=>$account,'password'=>'GeoLocal2026!','scene'=>1,'terminal'=>4]),CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true]);$login=json_decode(curl_exec($c),true);curl_close($c);gdCheck($login['code']===1,'isolated login '.$key);$owners[$key]=['mid'=>$mid,'uid'=>$u,'token'=>$login['data']['token']];}
