 $deleted=Geo::save(1,$u,['kind'=>'articles','title'=>'已回收文章','content'=>'测试']);Db::name('aigc_geo_article')->where('id',$deleted['id'])->update(['delete_time'=>time()]);Geo::save(1,$owners['b']['uid'],['kind'=>'articles','title'=>'其他商家文章','content'=>'不能混入首页']);
