 $sample(1,$u,'客户问题',$current,1);$sample(1,$u,'客户问题',$yesterday,0);$sample(1,$u,'历史问题',$old,1);$sample(1,$u,'人工问题',$current,1,'recorded_manual');$sample(1,$u,'失败问题',$current,1,'failed');$sample(1,$owners['b']['uid'],'其他商家问题',$current,1);$crossId=(int)$sample(99999,$u,'其他租户问题',$current,1);
 gdCheck(dashboardHttp()['code']===-1,'guest dashboard denied');gdCheck(dashboardHttp('bad',$token)['code']!==1,'invalid range denied');gdCheck(dashboardHttp('all',$token,true)['code']!==1,'dashboard only accepts GET');
 $all=dashboardHttp('all',$token);gdCheck($all['code']===1,'dashboard reads actual data');$d=$all['data'];gdCheck($d['stats']['articles']===3,'count excludes deleted and foreign articles');gdCheck($d['stats']['published']===2,'only actual published owned orders counted');gdCheck($d['stats']['samples']===3&&$d['stats']['mentions']===2,'automatic samples exclude failed manual and foreign records');$doubao=array_values(array_filter($d['platforms'],fn($r)=>$r['platform']==='豆包'))[0];gdCheck($doubao['questions']===2&&$doubao['samples']===3&&$doubao['mentions']===2,'distinct questions do not duplicate repeat sampling');$deepseek=array_values(array_filter($d['platforms'],fn($r)=>$r['platform']==='DeepSeek'))[0];gdCheck($deepseek['mentions']===null&&$deepseek['samples']===0,'unobserved platform remains unknown rather than zero exposure');gdCheck(count($d['recent_questions'])===2,'recent questions deduplicated per platform');gdCheck($d['latest_published'][1]['published_url']==='','unsafe published link omitted');gdCheck(!str_contains(json_encode($d),'cost_cents')&&!str_contains(json_encode($d),'其他商家')&&!str_contains(json_encode($d),'其他租户'),'dashboard omits upper costs and foreign details');
